-- IPA 2021-07-25 Q45–62: reviewed adaptations and verified repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210725-q45','exam-fe','カプセル化','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問45・改編】オブジェクト指向におけるカプセル化の説明はどれか。','[{"id":"a","text":"同じ性質を持つ複数のオブジェクトを抽象化して整理する"},{"id":"b","text":"基底クラスの性質を派生クラスに受け継がせる"},{"id":"c","text":"クラス間の共通する性質を抽出し基底クラスを作る"},{"id":"d","text":"データと手続を一つのオブジェクトにまとめ、詳細を外部から隠蔽する"}]','"d"','カプセル化はデータと操作をまとめ、内部実装を隠す。中文：封装将数据和操作组合，并隐藏内部实现。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q46','exam-fe','モジュール結合度','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問46・改編】モジュール間の情報の受渡しがパラメタだけで行われ、結合度が最も弱い結合はどれか。','[{"id":"a","text":"共通結合"},{"id":"b","text":"制御結合"},{"id":"c","text":"データ結合"},{"id":"d","text":"内容結合"}]','"c"','必要なデータを引数で渡すデータ結合が、選択肢の中では最も弱い。中文：数据耦合通过参数传递必要数据，在给定选项中耦合最弱。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q47','exam-fe','状態遷移図','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問47・改編】要求分析・設計で使う状態遷移図の説明はどれか。','[{"id":"a","text":"プログラム全体構造を階層構造で記述する"},{"id":"b","text":"状態を変化させるきっかけと、変化に伴って実行する動作を記述する"},{"id":"c","text":"システムの機能を概要から詳細へ段階的に記述する"},{"id":"d","text":"処理間のデータの流れをデータフロー、処理、データストア、外部の記号で記述する"}]','"b"','状態遷移図は状態、イベント、遷移時の動作を表す。中文：状态转换图描述状态、触发事件以及转换时的动作。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q49','exam-fe','XPのプラクティス','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問49・改編】XP（Extreme Programming）のプラクティスとして適切なものはどれか。','[{"id":"a","text":"顧客が単体テストの仕様に責任を持つ"},{"id":"b","text":"コードの結合とテストを継続的に繰り返す"},{"id":"c","text":"コードを書き結合できると確認した後でテストケースを作る"},{"id":"d","text":"テストを通過したコードは次の反復までリファクタリングしない"}]','"b"','XPでは継続的インテグレーション、テスト、リファクタリングなどを重視する。中文：极限编程重视持续集成、持续测试和重构。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q50','exam-fe','ソフトウェアの使用許諾','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問50・改編】自社開発ソフトウェアの他社への使用許諾について適切なものはどれか。','[{"id":"a","text":"既に自社製品に搭載して販売している場合は単体で許諾できない"},{"id":"b","text":"ハードウェアと組み合わせて特許取得済みなら単体で許諾できない"},{"id":"c","text":"ソースコードを無償で許諾すると無条件でオープンソースになる"},{"id":"d","text":"特許で保護された技術を使っていないソフトウェアでも使用許諾できる"}]','"d"','特許の有無とソフトウェアの利用許諾は別。無償公開だけでオープンソースの条件を満たすとも限らない。中文：软件许可不以专利为必要条件；免费许可也不自动成为开源许可。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q52','exam-fe','アローダイアグラムの短縮','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問52・改編】作業ネットワークは、開始→中間1:A(6日)、開始→中間2:B(3日)、中間2→中間1:C(4日)、中間1→終了:D(2日)、中間2→中間3:E(4日)、中間3→終了:F(1日)。各節点は流入する全作業の完了を待つ。A〜Eのうち選択肢の作業を各1日短縮すると、全体を2日短縮できる組合せはどれか。','[{"id":"a","text":"A,C,E"},{"id":"b","text":"A,D"},{"id":"c","text":"B,C,E"},{"id":"d","text":"B,D"}]','"d"','経路はA→D=8日、B→C→D=9日、B→E→F=8日。BとDを各1日短縮すると全経路の最長は7日になり、全体が2日短縮する。中文：三条路径原为8、9、8天；B和D各缩短一天后最长为7天。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q54','exam-fe','工程別の要員','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問54・改編】期間10か月、工数200人月のプロジェクト。工程（要件定義、設計、開発・テスト、システムテスト）の工数配分は16%、33%、42%、9%、期間配分は20%、30%、40%、10%。各工程の要員数はその工程中一定とする。ピーク時の要員は何人か。','[{"id":"a","text":"18"},{"id":"b","text":"20"},{"id":"c","text":"21"},{"id":"d","text":"22"}]','"d"','各工程は工数(32,66,84,18)人月、期間(2,3,4,1)か月なので要員は(16,22,21,18)人。最大22人。中文：各阶段人数依次为16、22、21、18，峰值为22人。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q57','exam-fe','エラープルーフ化','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問57・改編】運用作業におけるエラープルーフ化の例として最も適切なものはどれか。','[{"id":"a","text":"複数ウィンドウを間違えないよう背景色をそれぞれ変える"},{"id":"b","text":"長時間監視の疲労を減らすため2時間おきに休憩する"},{"id":"c","text":"過去のヒヤリハット情報を共有する"},{"id":"d","text":"臨時作業の教育や訓練を定期的に行う"}]','"a"','作業対象を色で区別し間違いを起こしにくくする仕組みがエラープルーフ化。中文：用不同背景色直接减少误操作，属于防错设计。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q58','exam-fe','システム監査手続','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問58・改編】システム監査の監査手続として最も適切なものはどれか。','[{"id":"a","text":"監査計画の立案や進捗管理の手順"},{"id":"b","text":"監査報告書に結論や指摘事項を記述する手順"},{"id":"c","text":"監査項目について十分かつ適切な証拠を入手する手順"},{"id":"d","text":"監査テーマに合わせ監査チームを編成する手順"}]','"c"','監査手続は監査目的を達成するため、十分かつ適切な証拠を集める具体的方法。中文：审计程序是为审计项目取得充分、适当证据的方法。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q59','exam-fe','電子証明書の有効期間','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問59・改編】公開鍵証明書の有効期間を取得日から4年間とし、更新と失効を考慮しない。電子署名の生成日と検証日の両方に証明書が有効となる組（取得日、署名生成日、検証日）はどれか。','[{"id":"a","text":"2012/3/1、2014/8/1、2018/12/1"},{"id":"b","text":"2014/1/1、2016/12/1、2018/2/1"},{"id":"c","text":"2015/4/1、2015/5/1、2018/12/1"},{"id":"d","text":"2016/8/1、2014/7/1、2018/3/1"}]','"c"','Cの有効期間は2015年4月から2019年4月までで署名日と検証日を含む。A・Bは検証時に期限切れ、Dは署名時に未取得。中文：C在证书有效期内签署和验证；A、B验证时已过期，D签署时尚未取得。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q60','exam-fe','内部統制の責任','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問60・改編】日本の証券取引所上場企業で、内部統制の整備及び運用に最終的な責任を負う者は誰か。','[{"id":"a","text":"株主"},{"id":"b","text":"監査役"},{"id":"c","text":"業務担当者"},{"id":"d","text":"経営者"}]','"d"','内部統制の整備・運用の最終的責任は経営者が負う。中文：内部控制的建立和运行最终由经营者负责。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q61','exam-fe','投資回収期間','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問61・改編】IT機器aは投資90万円・回収期間3年、bは投資300万円・回収期間5年。年間利益は毎年均等で利益全額を回収に充て、利率を考慮しない。期間内に回収する最低年間利益の比較はどれか。','[{"id":"a","text":"aとbは同額"},{"id":"b","text":"aはbの2倍"},{"id":"c","text":"bはaの1.5倍"},{"id":"d","text":"bはaの2倍"}]','"d"','aは90÷3=30万円/年、bは300÷5=60万円/年なのでbはaの2倍。中文：a每年需30万日元，b每年需60万日元，b为a的两倍。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210725-q62','exam-fe','CRM','standard','single_choice','【IPA 2021年度 修了認定試験 2021-07-25 問62・改編】顧客に対するワントゥワンマーケティングを実現する統合的なソリューションはどれか。','[{"id":"a","text":"CRM"},{"id":"b","text":"HRM"},{"id":"c","text":"SCM"},{"id":"d","text":"財務管理"}]','"a"','CRMは顧客情報や接点を管理・活用し、顧客ごとに適切な対応を支援する。中文：客户关系管理利用客户信息支持个性化营销。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210725_FE.pdf','ja','A','explicit','standard','fe_exemption');
